    },
    {
      "scene_number": 3,
      "caption": "Armored patrol marches past a broken fountain.",
      "visual_description": "Three guards in rusted plate armor carrying polearms, their helmets visored, as they step over rubble near a dry fountain.",
      "characters": ["patrol_leader", "patrol_guard_1", "patrol_guard_2"]
    },
    {
      "scene_number": 4,
      "caption": "The party hides in an abandoned clothier's shop.",
      "visual_description": "Dusty bolts of fabric and a shattered loom; the scout peers through a cracked window as the patrol passes.",
      "characters": ["scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 5,
      "caption": "A magic door blocks the alley to the tower.",
