      "characters": ["magic_helper", "scout"]
    },
    {
      "scene_number": 7,
      "caption": "The door opens into a cursed tower courtyard.",
      "visual_description": "A spiral of black thorn vines coils up the tower walls; a single raven perches on a rusted bell, and the ground is cracked stone.",
      "characters": ["magic_helper", "scout", "map_reader"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the tower, illusions of treasure appear.",
      "visual_description": "Golden coins and jeweled goblets float in midair, flickering like mirages around a central pedestal holding a crystal key.",
      "characters": ["scout", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 9,
      "caption": "The scout resists a tempting crown on a cushion.",
      "visual_description": "A velvet cushion with a ruby crown floats before the scout, whose hand reaches out but stops, eyes narrowed in suspicion.",
      "characters": ["scout", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 10,
      "caption": "A hallucination of a dragon casts a moving shadow.",
      "visual_description": "Across the curved tower wall, the shadow of a great winged beast glides, though no dragon is visible in the room.",
      "characters": ["scout", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 11,
      "caption": "The party takes the crystal key from the pedestal.",
      "visual_description": "The magic helper carefully lifts a glowing crystal key from the pedestal; the floating illusions vanish instantly.",
      "characters": ["magic_helper", "scout", "map_reader"]
    },
    {
      "scene_number": 12,
      "caption": "Old royal banners line the hall leading to the bridge controls.",
      "visual_description": "A long corridor with tattered gold-and-crimson banners hanging from iron rods, lit by sputtering torches in sconces.",
      "characters": ["scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 13,
      "caption": "Armored guards confront the party in the hall.",
      "visual_description": "Two guards step from side alcoves, shields raised and swords drawn, blocking the way forward.",
      "characters": ["patrol_leader", "patrol_guard_1", "scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 14,
      "caption": "The scout disarms one guard with a quick maneuver.",
      "visual_description": "The scout ducks under a sword swing and kicks the guard's knee, sending him stumbling; the second guard hesitates.",
      "characters": ["scout", "patrol_guard_1", "patrol_leader", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 15,
      "caption": "The party reaches the bridge control room.",
      "visual_description": "A small chamber with a large lever on a stone console, and a broken window overlooking the chasm and the bridge beyond.",
      "characters": ["scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 16,
      "caption": "The map reader pulls the lever to lower the bridge.",
      "visual_description": "The map reader grips the iron lever with both hands and pulls; outside, the bridge sections begin to lower with a grinding noise.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 17,
      "caption": "The party races across the lowering bridge.",
      "visual_description": "Stone bridge sections still settling, gaps showing the dark chasm below; the party runs single-file, arms outstretched for balance.",
      "characters": ["scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 18,
      "caption": "They escape as the bridge collapses behind them.",
      "visual_description": "The last stone slab tips into the chasm as the party reaches solid ground; dust and rubble rise while the ruined city looms beyond.",
      "characters": ["scout", "map_reader", "magic_helper"]
    }
  ]
}
```

